static NSDictionary *Mach(NSData *d){if(d.length<32)return nil;struct mach_header_64 h;memcpy(&h,d.bytes,32);if(h.magic!=MH_MAGIC_64||h.ncmds>10000||h.sizeofcmds>d.length-32)return nil;NSMutableArray *loads=[NSMutableArray new],*rpaths=[NSMutableArray new];NSString *identifier=@"";NSUInteger p=32,end=32+h.sizeofcmds;for(NSUInteger i=0;i<h.ncmds;i++){struct load_command c;if(p>end||end-p<8)return nil;memcpy(&c,(const char *)d.bytes+p,8);if(c.cmdsize<8||c.cmdsize>end-p)return nil;if((c.cmd==LC_LOAD_DYLIB||c.cmd==LC_LOAD_WEAK_DYLIB||c.cmd==LC_REEXPORT_DYLIB||c.cmd==LC_ID_DYLIB)&&c.cmdsize>=24){uint32_t off;memcpy(&off,(const char *)d.bytes+p+8,4);if(off<24||off>=c.cmdsize)return nil;NSString *s=CString(d,p+off,p+c.cmdsize);if(c.cmd==LC_ID_DYLIB)identifier=s;else[loads addObject:s];}if(c.cmd==LC_RPATH&&c.cmdsize>=12){uint32_t off;memcpy(&off,(const char *)d.bytes+p+8,4);if(off<12||off>=c.cmdsize)return nil;[rpaths addObject:CString(d,p+off,p+c.cmdsize)];}p+=c.cmdsize;}uint32_t subtype=h.cpusubtype&0xffffff;NSString *cpu=h.cputype==CPU_TYPE_ARM64?(subtype==2?@"arm64e":@"arm64"):[NSString stringWithFormat:@"cpu-%u",h.cputype];return @{@"cpu":cpu,@"cpuType":@(h.cputype),@"cpuSubtype":@(h.cpusubtype),@"installName":identifier,@"rpaths":rpaths,@"dependencies":loads,@"bytes":@(d.length)};}
