static BOOL Tar(NSData *data,BOOL control,NSMutableDictionary *out,NSError **error){struct archive *a=archive_read_new();archive_read_support_filter_none(a);archive_read_support_filter_gzip(a);archive_read_support_filter_bzip2(a);archive_read_support_filter_xz(a);archive_read_support_filter_lzma(a);archive_read_support_format_tar(a);BOOL ok=archive_read_open_memory(a,data.bytes,data.length)==ARCHIVE_OK;struct archive_entry *e;NSUInteger count=0,total=0;int status=ARCHIVE_EOF;NSMutableArray *paths=[NSMutableArray new],*images=[NSMutableArray new];while(ok&&(status=archive_read_next_header(a,&e))==ARCHIVE_OK){if(++count>3000){ok=NO;break;}NSString *p=@(archive_entry_pathname(e)?:"");[paths addObject:p];if(archive_entry_filetype(e)!=AE_IFREG){archive_read_data_skip(a);continue;}la_int64_t size=archive_entry_size(e);if(size<0||(uint64_t)size>64*1024*1024||total+(uint64_t)size>128*1024*1024){ok=NO;break;}total+=(NSUInteger)size;BOOL isControl=control&&[p.lastPathComponent isEqual:@"control"];BOOL isImage=!control&&[p.pathExtension.lowercaseString isEqual:@"dylib"];if(!isControl&&!isImage){archive_read_data_skip(a);continue;}NSData *d=Read(a,isControl?256*1024:64*1024*1024);if(!d){ok=NO;break;}if(isControl){NSString *s=[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding];if(!s){ok=NO;break;}out[@"control"]=s;}else{NSArray *slices=Images(d);if(!slices){ok=NO;break;}[images addObject:@{@"path":p,@"slices":slices}];}}
