NSDictionary *TFAIInspectArtifact(NSData *data,NSString *name,NSError **error){if(!data.length||data.length>64*1024*1024){if(error)*error=Failure(@"产物检查支持 64 MB 内文件");return nil;}NSMutableDictionary *out=[@{@"file":name.lastPathComponent,@"bytes":@(data.length),@"inspection":@"本机只读解析；未执行文件或安装脚本；包架构标识与 CPU 架构分别报告"} mutableCopy];if([name.pathExtension.lowercaseString isEqual:@"dylib"]){NSArray *s=Images(data);if(!s){if(error)*error=Failure(@"未识别为受支持的 Mach-O 动态库");return nil;}out[@"slices"]=s;return out;}if(![name.pathExtension.lowercaseString isEqual:@"deb"]){if(error)*error=Failure(@"请选择 deb 或 dylib");return nil;}struct archive *a=archive_read_new();archive_read_support_format_ar(a);BOOL ok=archive_read_open_memory(a,data.bytes,data.length)==ARCHIVE_OK;struct archive_entry *e;NSUInteger count=0;int status=ARCHIVE_EOF;BOOL version=NO,control=NO,payload=NO;while(ok&&(status=archive_read_next_header(a,&e))==ARCHIVE_OK){NSString *p=@(archive_entry_pathname(e)?:"");if(++count>20){ok=NO;break;}BOOL ct=[p hasPrefix:@"control.tar"],dt=[p hasPrefix:@"data.tar"];if([p isEqual:@"debian-binary"]){NSData *d=Read(a,16);version=[[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding] isEqual:@"2.0\n"];continue;}if(!ct&&!dt){archive_read_data_skip(a);continue;}if((ct&&control)||(dt&&payload)){ok=NO;break;}NSData *d=Read(a,64*1024*1024);if(!d||!Tar(d,ct,out,error)){ok=NO;break;}if(ct)control=YES;else payload=YES;}if(status!=ARCHIVE_EOF)ok=NO;archive_read_free(a);if(!ok||!version||!control||!payload||!out[@"control"]){if(error&&!*error)*error=Failure(@"Debian 包结构不完整或超出检查限制");return nil;}NSMutableDictionary *fields=[NSMutableDictionary new];for(NSString *line in [out[@"control"] componentsSeparatedByString:@"\n"]){NSRange r=[line rangeOfString:@":"];if(r.location!=NSNotFound)fields[[line substringToIndex:r.location]]=[[line substringFromIndex:r.location+1] stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];}out[@"controlFields"]=fields;return out;}
